using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AstriumEffect", menuName = "Data/Battle/Effects/Orion/Astrium Effect")]
public class AstriumEffect : Effect
{
	[Header("Astrium")]
	[SerializeField]
	private int amountToTriggerAstrium;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private int purifyAmount;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[Header("Catalyst")]
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	[Header("Effects To Activate On Astrium Triggered")]
	[SerializeField]
	private Effect[] effectsToActivateOnTickTriggered;

	[Header("Achievement")]
	[SerializeField]
	private AchievementData astriumSpecialistAchievementData;

	public int AmountToTriggerAstrium => amountToTriggerAstrium;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return base.localizationManager.GetLocalizedWhenReachEffectActivateBaseFormatted(GetAstriumTriggerModifierText(), this, purifyAction.GetActionDescription(purifyAmount), GetAstriumTriggerModifierText());
	}

	private string GetAstriumTriggerModifierText()
	{
		_ = base.isOnBattleScene;
		return amountToTriggerAstrium.ToString();
	}

	private int GetAstriumTriggerReducerEffectAmount(bool activateFeedback)
	{
		return 0;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		EffectIncreased(effectAmount, effectOwner, source);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (effectAmount >= amountToTriggerAstrium)
		{
			PlayerEffects component = effectOwner.GetComponent<PlayerEffects>();
			ReferenceSingleton<OrionOmensHandler>.Instance.ActivateAstriumActivatedOmens();
			omenLogic.ActivateOmen(null, purifyAmount, null, null);
			for (int i = 0; i < effectsToActivateOnTickTriggered.Length; i++)
			{
				component.IsEffectActiveWithActivation(effectsToActivateOnTickTriggered[i]);
			}
			if (!astriumSpecialistAchievementData.IsUnlocked())
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AstriumActivatedAmount++;
				if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AstriumActivatedAmount >= astriumSpecialistAchievementData.AchievementVariableAmount)
				{
					astriumSpecialistAchievementData.Unlock();
				}
			}
			component.IsEffectActive(this);
			component.IsEffectActiveAndDecreaseEffect(this, amountToTriggerAstrium, activateFeedback: false);
			component.IsEffectActiveWithActivation(playerEffectsList.CatalystEffect);
			PlaySecondEffectActivationSFX();
			SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
		else
		{
			PlayEffectActivationSFX();
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 3f);
		}
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		EffectIncreased(effectAmount, effectOwner, null);
		return effectAmount;
	}
}
